func BubbleSort(arr []int) {
	n := len(arr)
	for i := 0; i < n; i++ {
		for j := 0; j < n-1; j++ {
			if arr[j] > arr[j+1] {
				arr[j], arr[j+1] = arr[j+1], arr[j]
			}
		}
	}
}

func SelectionSort(arr []int) {
	n := len(arr)
	for i := 0; i < n; i++ {
		minIdx := i
		for j := i + 1; j < n; j++ {
			if arr[j] < arr[minIdx] {
				minIdx = j
			}
		}
		arr[i], arr[minIdx] = arr[minIdx], arr[i]
	}
}

func InsertionSort(arr []int) {
	for i := 1; i < len(arr); i++ {
		key := arr[i]
		j := i - 1
		for j >= 0 && arr[j] > key {
			arr[j+1] = arr[j]
			j--
		}
		arr[j+1] = key
	}
}

func CountPairsGreater(arr []int, target int) int {
	n := len(arr)
	count := 0
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			if arr[i]+arr[j] > target {
				count++
			}
		}
	}
	return count
}

func FindDuplicates(arr []int) []int {
	n := len(arr)
	dups := []int{}
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			if arr[i] == arr[j] {
				dups = append(dups, arr[i])
				break
			}
		}
	}
	return dups
}

func HasAnyDuplicate(arr []int) bool {
	n := len(arr)
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			if arr[i] == arr[j] {
				return true
			}
		}
	}
	return false
}

func IdentityMatrix(n int) [][]int {
	m := make([][]int, n)
	for i := 0; i < n; i++ {
		m[i] = make([]int, n)
		for j := 0; j < n; j++ {
			if i == j {
				m[i][j] = 1
			}
		}
	}
	return m
}

func AddMatrices(a, b [][]int) [][]int {
	n := len(a)
	res := make([][]int, n)
	for i := 0; i < n; i++ {
		res[i] = make([]int, n)
		for j := 0; j < n; j++ {
			res[i][j] = a[i][j] + b[i][j]
		}
	}
	return res
}

func Transpose(mat [][]int) [][]int {
	n := len(mat)
	res := make([][]int, n)
	for i := 0; i < n; i++ {
		res[i] = make([]int, n)
		for j := 0; j < n; j++ {
			res[j][i] = mat[i][j]
		}
	}
	return res
}

func AllPairsProduct(arr []int) int {
	n := len(arr)
	sum := 0
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			sum += arr[i] * arr[j]
		}
	}
	return sum
}

func AllAbsDistances(arr []int) []int {
	n := len(arr)
	res := make([]int, 0, n*(n-1)/2)
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			d := arr[i] - arr[j]
			if d < 0 { d = -d }
			res = append(res, d)
		}
	}
	return res
}

func IsAnagramNaive(a, b string) bool {
	ra := []rune(a)
	rb := []rune(b)
	if len(ra) != len(rb) { return false }

	used := make([]bool, len(rb))
	for i := 0; i < len(ra); i++ {
		found := false
		for j := 0; j < len(rb); j++ {
			if !used[j] && ra[i] == rb[j] {
				used[j] = true
				found = true
				break
			}
		}
		if !found { return false }
	}
	return true
}

func CountInversions(arr []int) int {
	n := len(arr)
	inv := 0
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			if arr[i] > arr[j] {
				inv++
			}
		}
	}
	return inv
}

