func MaxPairProduct(arr []int) int {
	n := len(arr)
	maxP := -1 << 31
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			p := arr[i] * arr[j]
			if p > maxP { maxP = p }
		}
	}
	return maxP
}

