func BuildAdjMatrixNaive(n int, edges []Edge) [][]int {
	mat := make([][]int, n)
	for i := 0; i < n; i++ {
		mat[i] = make([]int, n)
	}
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			for _, e := range edges {
				if (e.U == i && e.V == j) || (e.U == j && e.V == i) {
					mat[i][j] = 1
					break
				}
			}
		}
	}
	return mat
}

